fn solve(input: Vec<char>) -> Vec<char> {
    // Extract first two characters (guaranteed to be digits)
    let first_char = input[0];
    let second_char = input[1];
    
    // Helper function to map digit char to its good count
    fn good_count(digit: char) -> u8 {
        match digit {
            '0' => 2,
            '1' => 7,
            '2' => 2,
            '3' => 3,
            '4' => 3,
            '5' => 4,
            '6' => 2,
            '7' => 5,
            '8' => 1,
            '9' => 2,
            _ => 0, // This case shouldn't happen per problem constraints
        }
    }
    
    // Get good counts for both digits
    let count1 = good_count(first_char);
    let count2 = good_count(second_char);
    
    // Compute product (guaranteed to fit in u8 and be between 1-49)
    let product = (count1 as u16) * (count2 as u16);
    
    // Convert product to string and then to Vec<char>
    let mut result: Vec<char> = product.to_string().chars().collect();
    
    // Append newline character
    result.push('\n');
    
    result
}